import{Q as e,it as t,t as n,tt as r,xt as i}from"./chunks/framework.CuR1irRm.js";var a=JSON.parse(`{"title":"Document replica event delivery","description":"","frontmatter":{},"headers":[],"relativePath":"limitation/document-replica-events.md","filePath":"limitation/document-replica-events.md"}`),o={name:`limitation/document-replica-events.md`};function s(n,a,o,s,c,l){return i(),r(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794061796000`},[...a[0]||=[e(`h1`,{id:`document-replica-event-delivery`,tabindex:`-1`},[t(`Document replica event delivery `),e(`a`,{class:`header-anchor`,href:`#document-replica-event-delivery`,"aria-label":`Permalink to “Document replica event delivery”`},`​`)],-1),e(`p`,null,`Keep the document service at one replica until event delivery and deletion races are fixed and verified with multi-replica integration tests. Redis synchronization alone does not solve this. The chart uses a Recreate deployment to avoid overlapping old and new pods during normal upgrades.`,-1),e(`p`,null,`Document pods share a Kafka consumer group, so an event reaches one group member, not every pod. Each pod owns its own WebSocket connections and loaded documents. Role-change and member-removal handlers only update or close connections on the pod that receives the event. A user connected to another pod may retain stale access until their connection is reauthenticated or closed.`,-1),e(`p`,null,`When a note is deleted, the document service deletes its associated document row and revisions. The receiving pod guards its loaded document against further stores, closes its local connections, and waits for local pending stores before deleting the row. Another pod may miss the event and subsequently upsert its loaded document, recreating the deleted row. The guard is local memory; the Hocuspocus Redis extension does not broadcast these application event handlers.`,-1),e(`p`,null,`Any fix must deliver revocations and deletion to all relevant live pods and coordinate deletion with stores across replicas. Test deletion during active edits and in-flight stores, role changes, member removal, pod restarts, and message delivery failures before allowing scale-out.`,-1)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};